SELECT p.product_name, p.product_price * ( (SELECT COUNT(*) FROM Regular_Order_Products rop WHERE rop.product_id = p.product_id) + (SELECT COUNT(*) FROM Actual_Order_Products aop WHERE aop.product_id = p.product_id) ) AS total_revenue
FROM Products p
WHERE p.product_price * ( (SELECT COUNT(*) FROM Regular_Order_Products rop WHERE rop.product_id = p.product_id) + (SELECT COUNT(*) FROM Actual_Order_Products aop WHERE aop.product_id = p.product_id) ) > 10000;
